mapper.select:
SELECT id, name, phone, position, work_area, restaurant, is_active
FROM schedule_employees


        restaurant = #{restaurant}


        AND work_area = #{workArea}


ORDER BY name

SELECT id, shift_code, restaurant, start_time, end_time FROM schedule_shifts
restaurant = #{restaurant}
ORDER BY shift_code

SELECT id, employee_id, schedule_date, value_type, value_code, notes, created_by
FROM schedule_records
WHERE employee_id = #{employeeId} AND schedule_date = #{date}

SELECT id, employee_id, record_date, get_checked, start_time, end_time, return_checked, restaurant
FROM phone_records
WHERE employee_id = #{employeeId} AND record_date = #{date}
